@push('head')<style>.checkout-form{display:grid;gap:14px;max-width:680px;margin:auto}.checkout-form input,.checkout-form textarea,.checkout-form select,#track-form input{width:100%;padding:14px;border:1px solid #e4ddd6;border-radius:10px;font:inherit}.checkout-form textarea{min-height:110px}.checkout-form .cols{display:grid;grid-template-columns:1fr 1fr;gap:12px}#track-form{display:grid;gap:12px;max-width:520px;margin:auto}.cart-row{display:grid;grid-template-columns:90px 1fr auto;gap:15px;align-items:center;padding:15px 0;border-bottom:1px solid #eee}.cart-row img{width:90px;height:90px;object-fit:contain;background:#f7f4f0;border-radius:12px}.cart-row button{padding:7px 11px;border:0;cursor:pointer}@media(max-width:550px){.checkout-form .cols{grid-template-columns:1fr}}</style>@endpush
@push('scripts')<script>
const fmtPKR=n=>'PKR '+Math.round(n).toLocaleString('en-PK');
if(@json($page)==='cart'){const el=document.getElementById('cart-content');function drawCart(){let a=AlAsraCart.read();el.innerHTML=a.length?a.map(i=>`<div class="cart-row"><img src="${i.image}" alt=""><div><b>${i.name}</b><p>${fmtPKR(i.price)} × ${i.qty}</p><button onclick="AlAsraCart.qty('${i.id}',-1);drawCart()">−</button> ${i.qty} <button onclick="AlAsraCart.qty('${i.id}',1);drawCart()">+</button></div><b>${fmtPKR(i.price*i.qty)}</b></div>`).join('')+`<h3 style="text-align:right">Subtotal: ${fmtPKR(a.reduce((s,i)=>s+i.price*i.qty,0))}</h3>`:'<p class="empty">Your bag is empty. <a href="/shop">Continue shopping</a>.</p>'}drawCart()}
if(@json($page)==='checkout'){document.getElementById('checkout-form').onsubmit=async e=>{e.preventDefault();let a=AlAsraCart.read();if(!a.length){document.getElementById('checkout-result').textContent='Your bag is empty.';return}let f=Object.fromEntries(new FormData(e.target));f.items=a.map(i=>({product_id:Number(i.id),quantity:i.qty}));try{let r=await fetch('/api/checkout',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(f)});let j=await r.json();if(!r.ok)throw new Error(j.message||Object.values(j.errors||{}).flat().join(' ')||'Could not place order');localStorage.removeItem('alasra-cart');AlAsraCart.render();document.getElementById('checkout-result').textContent='Order received: '+(j.data?.reference||'Your order has been placed.');e.target.reset()}catch(err){document.getElementById('checkout-result').textContent=err.message}}}
if(@json($page)==='track'){document.getElementById('track-form').onsubmit=async e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.target));try{let r=await fetch('/api/orders/track',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(f)}),j=await r.json();document.getElementById('track-result').textContent=r.ok?JSON.stringify(j.data):j.message||'Order not found'}catch{document.getElementById('track-result').textContent='Unable to track this order right now.'}}}
</script>@endpush
